// Rose Dragon controller: picks every plot's next farm from the live inventory.
// The flow's steps are the farms; this script decides when to enter and leave them.
// Rules: a farm is entered only when every item it places is in stock, and missing
// inputs are only re-placed when the stock covers all of them (never mutation debt).
const KNOBS = {"idle":"stay","single":[],"jellyStage":12,"aloeStage":10,"demand":"need","margin":1,"creditRunning":true,"startOnNeed":false,"stopOnNeed":false,"dupOnlyIfNeeded":false,"idleNeed":false,"order":"plot","rankBuilds":false,"handover":"uncommons"};
const D = {"goal":{"all_in_aloe":2,"devourer":2,"glasscorn":2,"phantomleaf":2,"timestalk":2},"low":{"choconut":21,"dustgrain":12,"gloomgourd":6,"shadevine":7,"ashwreath":9,"scourroot":12,"veilshroom":15,"witherbloom":12,"coalroot":12,"thornshade":6,"duskbloom":12,"chocoberry":7,"creambloom":10,"soggybud":13,"cindershade":4,"lonelily":9,"noctilume":7,"fleshtrap":2,"do_not_eat_shroom":16,"snoozling":4,"thunderling":6,"blastberry":5,"cheesebite":8,"chloronite":7,"magic_jellybean":6,"turtlellini":6,"puffercloud":4,"zombud":4,"startlevine":6,"chorus_fruit":7,"shellfruit":6,"stoplight_petal":5,"plantboy_advance":1,"all_in_aloe":2,"devourer":2,"glasscorn":2,"phantomleaf":2,"timestalk":2},"high":{"choconut":44,"dustgrain":29,"gloomgourd":17,"shadevine":11,"ashwreath":23,"scourroot":27,"veilshroom":30,"witherbloom":29,"coalroot":18,"thornshade":18,"duskbloom":36,"chocoberry":11,"creambloom":27,"soggybud":27,"cindershade":11,"lonelily":14,"noctilume":17,"fleshtrap":3,"do_not_eat_shroom":24,"snoozling":11,"thunderling":9,"blastberry":8,"cheesebite":8,"chloronite":20,"magic_jellybean":18,"turtlellini":6,"puffercloud":6,"zombud":6,"startlevine":6,"chorus_fruit":7,"shellfruit":6,"stoplight_petal":5,"plantboy_advance":2,"all_in_aloe":2,"devourer":2,"glasscorn":2,"phantomleaf":2,"timestalk":2},"down":{"dead_plant":["all_in_aloe","devourer","glasscorn","phantomleaf","timestalk"],"ashwreath":["all_in_aloe","devourer","glasscorn","phantomleaf","timestalk"],"choconut":["all_in_aloe","devourer","glasscorn","phantomleaf","timestalk"],"dustgrain":["all_in_aloe","devourer","glasscorn","phantomleaf","timestalk"],"gloomgourd":["all_in_aloe","devourer","glasscorn","phantomleaf","timestalk"],"scourroot":["all_in_aloe","devourer","glasscorn","phantomleaf","timestalk"],"shadevine":["all_in_aloe","devourer","glasscorn","phantomleaf","timestalk"],"veilshroom":["all_in_aloe","devourer","glasscorn","phantomleaf","timestalk"],"witherbloom":["all_in_aloe","devourer","glasscorn","phantomleaf","timestalk"],"duskbloom":["all_in_aloe","devourer","phantomleaf","timestalk"],"chocoberry":["glasscorn","phantomleaf","timestalk"],"lonelily":["all_in_aloe","devourer","phantomleaf","timestalk"],"cindershade":["all_in_aloe","devourer","phantomleaf","timestalk"],"coalroot":["devourer","glasscorn","phantomleaf","timestalk"],"creambloom":["all_in_aloe","devourer","glasscorn","phantomleaf","timestalk"],"thornshade":["all_in_aloe","devourer","glasscorn","phantomleaf","timestalk"],"chloronite":["glasscorn","phantomleaf","timestalk"],"do_not_eat_shroom":["devourer"],"soggybud":["all_in_aloe","glasscorn","phantomleaf","timestalk"],"magic_jellybean":["all_in_aloe","phantomleaf","timestalk"],"fermento":["glasscorn","phantomleaf","timestalk"],"blastberry":["glasscorn","phantomleaf","timestalk"],"cheesebite":["glasscorn"],"turtlellini":["phantomleaf","timestalk"],"noctilume":["all_in_aloe","phantomleaf","timestalk"],"fleshtrap":["devourer"],"snoozling":["all_in_aloe","devourer","phantomleaf","timestalk"],"thunderling":["all_in_aloe"],"zombud":["devourer"],"puffercloud":["devourer"],"stoplight_petal":["phantomleaf","timestalk"],"plantboy_advance":["all_in_aloe"],"startlevine":["glasscorn"],"chorus_fruit":["phantomleaf","timestalk"],"shellfruit":["phantomleaf","timestalk"],"devourer":["devourer"],"glasscorn":["glasscorn"],"phantomleaf":["phantomleaf"],"timestalk":["timestalk"],"all_in_aloe":["all_in_aloe"]},"jobs":{"commons":{"family":"commons","produces":["ashwreath","choconut","dustgrain","gloomgourd","scourroot","shadevine","veilshroom","witherbloom"],"cost":{"1":{"dead_plant":7},"2":{"dead_plant":10},"3":{"dead_plant":7}}},"commons-choconut":{"family":"commons","produces":["choconut","ashwreath"],"cost":{"1":{},"2":{},"3":{}},"focusOf":"commons","fallback":true},"uncommons-dusk":{"family":"uncommons","produces":["duskbloom","chocoberry"],"cost":{"1":{"choconut":18,"dustgrain":6,"gloomgourd":5,"shadevine":7},"2":{"choconut":18,"dustgrain":7,"gloomgourd":5,"shadevine":6},"3":{"choconut"